// Illustration only: cycles example requests and shows how each is broken into requirements.
const examples = [
  { q: "lightweight running shoes for a marathon under $150",
    tags: [["Category","Running"],["Need","Lightweight"],["Use","Marathon"],["Price","< $150"]] },
  { q: "black waterproof jacket for men, on sale",
    tags: [["Color","Black"],["Feature","Waterproof"],["Gender","Men"],["Type","Jacket"],["Deal","On sale"]] },
  { q: "a laptop for video editing under $1,200",
    tags: [["Category","Laptop"],["Use","Video editing"],["Price","< $1,200"]] },
];

const typed = document.getElementById("typed");
const tags = document.getElementById("tags");
document.getElementById("yr").textContent = new Date().getFullYear();

const sleep = ms => new Promise(r => setTimeout(r, ms));

async function run() {
  if (matchMedia("(prefers-reduced-motion: reduce)").matches) {
    typed.textContent = examples[0].q;
    examples[0].tags.forEach(t => tags.append(chip(t)));
    return;
  }
  for (let i = 0; ; i = (i + 1) % examples.length) {
    const { q, tags: ts } = examples[i];
    tags.textContent = "";
    for (let n = 1; n <= q.length; n++) { typed.textContent = q.slice(0, n); await sleep(38); }
    await sleep(300);
    for (const t of ts) { tags.append(chip(t)); await sleep(280); }
    await sleep(2600);
    for (let n = q.length; n >= 0; n--) { typed.textContent = q.slice(0, n); await sleep(12); }
  }
}

function chip([k, v]) {
  const el = document.createElement("span");
  el.className = "chip";
  const b = document.createElement("b");
  b.textContent = k;
  el.append(b, v);
  return el;
}

run();
// WebMCP: exposes the site's actions to in-browser AI agents (navigator.modelContext).
const BOOKING_URL = "https://calendly.com/marwan-coteloai/30-minute-meeting?month=2026-09";

if (navigator.modelContext && navigator.modelContext.registerTool) {
  const text = s => ({ content: [{ type: "text", text: s }] });

  navigator.modelContext.registerTool({
    name: "get_booking_link",
    description: "Get the link to book a 30-minute call with Cotelo to see AI search demoed on your own website.",
    inputSchema: { type: "object", properties: {} },
    annotations: { readOnlyHint: true },
    async execute() { return text(BOOKING_URL); },
  });

  navigator.modelContext.registerTool({
    name: "get_contact_email",
    description: "Get Cotelo's contact email address.",
    inputSchema: { type: "object", properties: {} },
    annotations: { readOnlyHint: true },
    async execute() { return text("marwan@coteloai.com"); },
  });

  navigator.modelContext.registerTool({
    name: "go_to_section",
    description: "Scroll the Cotelo page to a section: how, features, why-now, demos or contact.",
    inputSchema: {
      type: "object",
      properties: { section: { type: "string", enum: ["how", "features", "why-now", "demos", "contact"] } },
      required: ["section"],
    },
    async execute({ section }) {
      const el = document.getElementById(section);
      if (!el) return text("Unknown section: " + section);
      el.scrollIntoView({ behavior: "smooth" });
      return text("Scrolled to " + section);
    },
  });
}
